syntax:
struct StructName {
    type member1;
    type member2;
    ...
};

// Correct initializer order:
struct StructName s = { initializer_for_member1, initializer_for_member2, ... };

// Error example (incorrect order):
struct StructName s = { initializer_for_member2, initializer_for_member1 };

code_example:
struct Point {
    int x;
    int y;
};
